  1→@use '../theme/variables' as gt;
  2→@use '../theme/animations';
  3→
  4→:host {
  5→  display: block;
  6→}
  7→
  8→// Hero section — full-width gradient background
  9→.hero {
 10→  background: var(--gt-hero-bg);
 11→  text-align: center;
 12→  padding: 6rem 1.5rem;
 13→  animation: fadeInUp 0.6s ease-out both;
 14→
 15→  &__tagline {
 16→    font-size: gt.$hero-font-size;
 17→    font-weight: 800;
 18→    color: var(--gt-hero-text);
 19→    margin: 0 0 1.25rem;
 20→    line-height: 1.15;
 21→    letter-spacing: -0.02em;
 22→    max-width: gt.$max-width;
 23→    margin-left: auto;
 24→    margin-right: auto;
 25→  }
 26→
 27→  &__subtitle {
 28→    font-size: gt.$subtitle-font-size;
 29→    color: var(--gt-hero-subtitle);
 30→    margin: 0;
 31→    line-height: 1.6;
 32→    max-width: 640px;
 33→    margin-left: auto;
 34→    margin-right: auto;
 35→  }
 36→}
 37→
 38→// Feature highlights — alternating background
 39→.features {
 40→  background: var(--gt-surface-alt);
 41→  padding: gt.$section-padding;
 42→
 43→  &__grid {
 44→    display: grid;
 45→    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
 46→    gap: gt.$feature-grid-gap;
 47→    max-width: gt.$max-width;
 48→    margin: 0 auto;
 49→  }
 50→
 51→  &__heading {
 52→    text-align: center;
 53→    font-size: gt.$feature-heading-size;
 54→    font-weight: 700;
 55→    color: var(--gt-primary);
 56→    margin: 0 0 3rem;
 57→    max-width: gt.$max-width;
 58→    margin-left: auto;
 59→    margin-right: auto;
 60→  }
 61→
 62→  &__item {
 63→    background: var(--gt-surface);
 64→    border-radius: gt.$border-radius;
 65→    padding: gt.$card-padding;
 66→    box-shadow: var(--gt-card-shadow);
 67→    transition:
 68→      transform gt.$transition-base,
 69→      box-shadow gt.$transition-base;
 70→    animation: fadeInUp 0.6s ease-out both;
 71→
 72→    @for $i from 1 through 4 {
 73→      &:nth-child(#{$i}) {
 74→        animation-delay: #{0.05 + $i * 0.1}s;
 75→      }
 76→    }
 77→
 78→    &:hover {
 79→      transform: translateY(-4px);
 80→      box-shadow: var(--gt-card-shadow-hover);
 81→    }
 82→  }
 83→
 84→  &__icon {
 85→    font-size: gt.$feature-icon-size;
 86→    margin-bottom: 1rem;
 87→    display: block;
 88→  }
 89→
 90→  &__title {
 91→    font-size: gt.$feature-title-size;
 92→    font-weight: 700;
 93→    color: var(--gt-text);
 94→    margin: 0 0 0.75rem;
 95→  }
 96→
 97→  &__description {
 98→    color: var(--gt-text-secondary);
 99→    margin: 0;
100→    line-height: 1.7;
101→    font-size: gt.$feature-description-size;
102→  }
103→}
104→
105→// CTA section
106→// Note: The CTA button uses custom styling instead of Taiga UI's tuiButton directive
107→// because the design spec requires a shine-effect on hover (pseudo-element animation),
108→// which is not achievable through Taiga UI's button API. This is a deliberate deviation.
109→.cta {
110→  background: var(--gt-surface);
111→  text-align: center;
112→  padding: gt.$section-padding;
113→  animation: fadeInUp 0.6s ease-out both;
114→  animation-delay: 0.5s;
115→
116→  &__button {
117→    display: inline-block;
118→    position: relative;
119→    overflow: hidden;
120→    font-size: 1.15rem;
121→    padding: 0.85rem 2.5rem;
122→    border-radius: gt.$border-radius;
123→    background: linear-gradient(135deg, gt.$accent-orange, gt.$accent-orange-light);
124→    color: gt.$neutral-white;
125→    font-weight: 700;
126→    border: none;
127→    cursor: pointer;
128→    text-decoration: none;
129→    transition:
130→      transform gt.$transition-base,
131→      box-shadow gt.$transition-base;
132→
133→    // Shine effect on hover — uses transform instead of left for compositor-only animation
134→    &::after {
135→      content: '';
136→      position: absolute;
137→      top: -50%;
138→      left: 0;
139→      width: 50%;
140→      height: 200%;
141→      background: linear-gradient(
142→        90deg,
143→        transparent,
144→        rgba(255, 255, 255, 0.3),
145→        transparent
146→      );
147→      transform: translateX(-150%) skewX(-25deg);
148→      transition: transform 0.6s ease;
149→    }
150→
151→    &:hover {
152→      transform: translateY(-2px);
153→      box-shadow: 0 4px 20px rgba(253, 141, 50, 0.4);
154→
155→      &::after {
156→        transform: translateX(250%) skewX(-25deg);
157→      }
158→    }
159→
160→    &:active {
161→      transform: translateY(0);
162→    }
163→  }
164→}
165→
166→// Responsive
167→@media (max-width: 768px) {
168→  .hero {
169→    padding: 4rem 1rem;
170→
171→    &__tagline {
172→      font-size: gt.$hero-font-size-mobile;
173→    }
174→
175→    &__subtitle {
176→      font-size: 1.1rem;
177→    }
178→  }
179→
180→  .features {
181→    padding: gt.$section-padding-mobile;
182→
183→    &__heading {
184→      font-size: gt.$feature-heading-size-mobile;
185→      margin-bottom: gt.$feature-grid-gap;
186→    }
187→
188→    &__grid {
189→      grid-template-columns: 1fr;
190→      gap: 1.5rem;
191→    }
192→  }
193→
194→  .cta {
195→    padding: gt.$section-padding-mobile;
196→  }
197→}
