 1→import { TestBed } from '@angular/core/testing';
 2→import { LOCALE_ID, signal } from '@angular/core';
 3→import { TUI_DARK_MODE } from '@taiga-ui/core';
 4→import { AppComponent } from './app';
 5→import { appConfig } from './app.config';
 6→
 7→describe('i18n Configuration', () => {
 8→  beforeEach(async () => {
 9→    await TestBed.configureTestingModule({
10→      imports: [AppComponent],
11→      providers: [
12→        ...appConfig.providers,
13→        { provide: TUI_DARK_MODE, useValue: signal(false) },
14→      ],
15→    }).compileComponents();
16→  });
17→
18→  it('should provide a LOCALE_ID', () => {
19→    const localeId = TestBed.inject(LOCALE_ID);
20→    expect(localeId).toBeTruthy();
21→  });
22→
