import { TestBed } from '@angular/core/testing';
import { signal, WritableSignal } from '@angular/core';
import { provideRouter } from '@angular/router';
import { TUI_DARK_MODE } from '@taiga-ui/core';
import { HeaderComponent } from './header';
import { ThemeService } from '../theme';

describe('HeaderComponent', () => {
  let darkModeSignal: WritableSignal<boolean>;

  beforeEach(async () => {
    darkModeSignal = signal(false);

    await TestBed.configureTestingModule({
      imports: [HeaderComponent],
      providers: [
        provideRouter([]),
        { provide: TUI_DARK_MODE, useValue: darkModeSignal },
      ],
    }).compileComponents();
  });

  it('should render a header element with the app-header test id', () => {
    const fixture = TestBed.createComponent(HeaderComponent);
    fixture.detectChanges();

    const header = fixture.nativeElement.querySelector('[data-testid="app-header"]');
    expect(header).toBeTruthy();
  });

  it('should render a Home navigation link', () => {
    const fixture = TestBed.createComponent(HeaderComponent);
    fixture.detectChanges();

    const homeLink = fixture.nativeElement.querySelector('[data-testid="nav-home"]');
    expect(homeLink).toBeTruthy();
    expect(homeLink.textContent.trim()).toBe('Home');
  });

  it('should render a Learn navigation link', () => {
    const fixture = TestBed.createComponent(HeaderComponent);
    fixture.detectChanges();

    const learnLink = fixture.nativeElement.querySelector('[data-testid="nav-learn"]');
    expect(learnLink).toBeTruthy();
    expect(learnLink.textContent.trim()).toBe('Learn');
  });

  it('should render a theme toggle button', () => {
    const fixture = TestBed.createComponent(HeaderComponent);
    fixture.detectChanges();

    const toggle = fixture.nativeElement.querySelector('[data-testid="theme-toggle"]');
    expect(toggle).toBeTruthy();
  });

  it('should toggle theme when theme toggle button is clicked', () => {
    const fixture = TestBed.createComponent(HeaderComponent);
    fixture.detectChanges();

    const themeService = TestBed.inject(ThemeService);
    expect(themeService.isDarkMode()).toBe(false);

    const toggle = fixture.nativeElement.querySelector('[data-testid="theme-toggle"]');
    toggle.click();
    fixture.detectChanges();

    expect(themeService.isDarkMode()).toBe(true);
  });

  it('should render a language selector with NL, DE, EN options', () => {
    const fixture = TestBed.createComponent(HeaderComponent);
    fixture.detectChanges();

    const langSelector = fixture.nativeElement.querySelector('[data-testid="language-selector"]');
    expect(langSelector).toBeTruthy();

    const options = fixture.nativeElement.querySelectorAll('[data-testid="language-option"]');
    expect(options.length).toBe(3);

    const labels = Array.from(options).map((o: any) => o.textContent.trim());
    expect(labels).toContain('NL');
    expect(labels).toContain('DE');
    expect(labels).toContain('EN');
  });

  it('should highlight EN as the active language by default', () => {
    const fixture = TestBed.createComponent(HeaderComponent);
    fixture.detectChanges();

    const activeOption = fixture.nativeElement.querySelector('[data-testid="language-option"].active');
    expect(activeOption).toBeTruthy();
    expect(activeOption.textContent.trim()).toBe('EN');
  });

  it('should link Home to the root route', () => {
    const fixture = TestBed.createComponent(HeaderComponent);
    fixture.detectChanges();

    const homeLink = fixture.nativeElement.querySelector('[data-testid="nav-home"]');
    expect(homeLink.getAttribute('href')).toBe('/');
  });

  it('should link Learn to the /learn route', () => {
    const fixture = TestBed.createComponent(HeaderComponent);
    fixture.detectChanges();

    const learnLink = fixture.nativeElement.querySelector('[data-testid="nav-learn"]');
    expect(learnLink.getAttribute('href')).toBe('/learn');
  });
});

import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { RouterLink } from '@angular/router';
import { ThemeService } from '../theme';

@Component({
  selector: 'app-header',
  imports: [RouterLink],
  templateUrl: './header.html',
  styleUrl: './header.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class HeaderComponent {
  protected readonly themeService = inject(ThemeService);
  protected readonly languages = ['NL', 'DE', 'EN'] as const;
  protected activeLanguage = 'EN';

  toggleTheme(): void {
    this.themeService.toggleTheme();
  }
}

@use '../theme/variables' as gt;

:host {
  display: block;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1.5rem;
  background: var(--gt-surface);
  border-bottom: 1px solid var(--tui-border-normal, #{gt.$neutral-light});
  max-width: 100%;

  &__nav {
    display: flex;
    gap: 1.5rem;
  }

  &__link {
    color: var(--gt-text);
    text-decoration: none;
    font-weight: 600;
    font-size: 0.95rem;
    transition: color gt.$transition-base;

    &:hover {
      color: var(--gt-accent);
    }
  }

  &__actions {
    display: flex;
    align-items: center;
    gap: 1rem;
  }

  &__theme-toggle {
    background: none;
    border: 1px solid var(--tui-border-normal, #{gt.$neutral-light});
    border-radius: gt.$border-radius;
    padding: 0.35rem 0.6rem;
    cursor: pointer;
    color: var(--gt-text);
    font-size: 1.1rem;
    line-height: 1;
    transition:
      background gt.$transition-base,
      border-color gt.$transition-base;

    &:hover {
      background: var(--gt-neutral);
      border-color: var(--gt-accent);
    }
  }

  &__theme-icon {
    display: inline-block;
  }

  &__language-selector {
    display: flex;
    gap: 0.25rem;
  }

  &__language-option {
    background: none;
    border: 1px solid transparent;
    border-radius: gt.$border-radius;
    padding: 0.25rem 0.5rem;
    cursor: pointer;
    color: var(--gt-text-secondary);
    font-size: 0.8rem;
    font-weight: 600;
    transition:
      color gt.$transition-base,
      border-color gt.$transition-base,
      background gt.$transition-base;

    &:hover {
      color: var(--gt-text);
      border-color: var(--tui-border-normal, #{gt.$neutral-light});
    }

    &.active {
      color: var(--gt-accent);
      border-color: var(--gt-accent);
      background: var(--gt-neutral);
    }
  }
}

@media (max-width: 768px) {
  .header {
    padding: 0.5rem 1rem;

    &__nav {
      gap: 1rem;
    }

    &__actions {
      gap: 0.5rem;
    }
  }
}

