<header data-testid="app-header" class="header">
  <nav class="header__nav">
    <a data-testid="nav-home" class="header__link" routerLink="/" i18n="Navigation home link@@nav.home">Home</a>
    <a data-testid="nav-learn" class="header__link" routerLink="/learn" i18n="Navigation learn link@@nav.learn">Learn</a>
  </nav>

  <div class="header__actions">
    <button
      data-testid="theme-toggle"
      class="header__theme-toggle"
      type="button"
      (click)="toggleTheme()"
