    <div data-testid="language-selector" class="header__language-selector" role="group" aria-label="Language selector" i18n-aria-label="Language selector aria label@@header.languageSelector.ariaLabel">
      @for (lang of languages; track lang) {
        <button
          data-testid="language-option"
          class="header__language-option"
          [class.active]="lang === activeLanguage"
          type="button"
          [attr.aria-label]="lang"
          [attr.aria-pressed]="lang === activeLanguage"
        >
          {{ lang }}
        </button>
      }
    </div>
  </div>
</header>

